logs=np.log2(valid['avg_glucose_level']); q1l,q3l=logs.quantile(.25), logs.quantile(.75); hil=q3l+3*(q3l-q1l)
A=[]; B=[]
for idx,row in raw_out[['avg_glucose_level','stroke']].iterrows():
    peers=valid[(valid['avg_glucose_level']==row['avg_glucose_level'])&(valid.index!=idx)]
    ratioA=peers['stroke'].mean() if len(peers) else 0
    is_out=True
    if ratioA>=0.5:
        is_out=False
    elif ratioA>0.2:
        if logs.loc[idx] <= hil:
            is_out=False
        else:
            peers2=valid[(np.log2(valid['avg_glucose_level'])==logs.loc[idx])&(valid.index!=idx)]
            ratio2=peers2['stroke'].mean() if len(peers2) else 0
            if ratio2>=0.5:
                is_out=False
    if is_out: A.append(idx)
    group=valid[valid['avg_glucose_level']==row['avg_glucose_level']]
